#include <graphx.h>
#include <keypadc.h>
#include <fileioc.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <stdlib.h>
#include "abyss.h"

enum { TITLE, LOBBY, SELECT, UPGRADE, COLLECTION, STATS, PLAY, PAUSE, ENDING };
typedef struct { char magic[4]; uint8_t version, unlocked, armor, health, energy; uint32_t coins, complete, treasure, secrets, deaths, checksum; } Save;
typedef struct { int16_t x,y,vx,vy; uint8_t grounded,face,anim,invuln,hp,energy; } Player;
static Save save;
static Player p;
static char room[MAP_H][MAP_W];
static uint8_t scene=TITLE, choice=0, level=0, prior[8], seals=0, flash=0;
static int16_t cam=0, creature=480, dir=-1;
static uint16_t tick=0;
static uint8_t bits(uint32_t n){uint8_t c=0;while(n){c+=(uint8_t)(n&1);n>>=1;}return c;}

static uint32_t hash(const Save *s){const uint8_t *b=(const uint8_t*)s;uint32_t h=2166136261u;for(uint16_t i=0;i<sizeof(Save)-4;i++){h^=b[i];h*=16777619u;}return h;}
static void defaults(void){memset(&save,0,sizeof(save));memcpy(save.magic,"ABYS",4);save.version=1;save.unlocked=1;save.energy=1;}
static void save_game(void){save.checksum=hash(&save);uint8_t h=ti_Open("ABYSSSV","w");if(h){ti_Write(&save,sizeof(save),1,h);ti_SetArchiveStatus(true,h);ti_Close(h);}}
static void load_game(void){uint8_t h=ti_Open("ABYSSSV","r");if(!h){defaults();save_game();return;}Save s;size_t n=ti_Read(&s,sizeof(s),1,h);ti_Close(h);if(n!=1||memcmp(s.magic,"ABYS",4)||s.version!=1||s.checksum!=hash(&s)||!s.unlocked||s.unlocked>20||s.armor>3||s.health>3){defaults();save_game();}else save=s;}
static void before_gc(void){gfx_End();}
static void after_gc(void){gfx_Begin();gfx_SetDrawBuffer();}
static bool held(uint8_t *k,uint8_t g,uint8_t b){return (k[g]&b)!=0;}
static bool pressed(uint8_t *k,uint8_t g,uint8_t b){return held(k,g,b)&&!(prior[g]&b);}
static void input(uint8_t *k){kb_Scan();memcpy(k,kb_Data,8);}
static uint8_t color(uint8_t w,uint8_t n){return (uint8_t)(18+w*7+n);}
static void palette(uint8_t w){static const uint8_t rgb[4][6][3]={{{23,37,59},{48,66,91},{98,119,140},{121,100,143},{198,220,174},{224,234,223}},{{16,56,69},{31,87,101},{66,130,133},{130,99,64},{115,229,220},{217,246,239}},{{42,19,28},{92,27,36},{154,51,27},{220,95,19},{255,205,73},{255,238,174}},{{18,12,41},{51,29,86},{98,52,151},{78,160,233},{220,201,255},{255,249,255}}};for(uint8_t i=0;i<6;i++)gfx_palette[color(w,i)]=gfx_RGBTo1555(rgb[w&3][i][0],rgb[w&3][i][1],rgb[w&3][i][2]);}
static void draw_text(int x,int y,const char *s){gfx_SetTextXY(x,y);gfx_PrintString(s);}
static void num(int x,int y,uint32_t n,uint8_t digits){gfx_SetTextXY(x,y);gfx_PrintUInt(n,digits);}
static void begin_level(uint8_t n){if(n>=LEVEL_COUNT)n=0;level=n;for(uint8_t y=0;y<MAP_H;y++)memcpy(room[y],abyss_levels[n].rows[y],MAP_W);p.x=16;p.y=192;p.vx=p.vy=0;p.grounded=0;p.face=1;p.hp=(uint8_t)(100+save.health*25);p.energy=(uint8_t)(20+save.energy*10);p.invuln=0;cam=0;creature=500;dir=-1;seals=0;scene=PLAY;}
static bool solid(int x,int y){int tx=x/TILE,ty=y/TILE;if(tx<0||tx>=MAP_W||ty>=MAP_H)return ty>=MAP_H;if(ty<0)return false;char c=room[ty][tx];return c=='#'||c=='=';}
static void pulse(void){if(p.energy<2)return;p.energy-=2;int tx=(p.x+8)/TILE,ty=(p.y+8)/TILE;bool found=false;for(int y=ty-2;y<=ty+2;y++)for(int x=tx-3;x<=tx+3;x++)if(x>=0&&x<MAP_W&&y>=0&&y<MAP_H&&room[y][x]=='r'){room[y][x]='.';found=true;}if(found){if(level%5==4&&seals<3)seals++;save.secrets|=1UL<<level;save_game();flash=12;}}
static void reward(void){uint32_t bit=1UL<<level;if(!(save.complete&bit)){save.complete|=bit;save.coins+=12;if(level%5==4)save.coins+=25;}if(save.unlocked<20&&save.unlocked<=level+1)save.unlocked=level+2;if(level==2||level==5||level==8||level==11||level==15||level==19)save.secrets|=1UL<<level;save_game();if(level==19)scene=ENDING;else scene=LOBBY;}
static void collect(int x,int y){char *t=&room[y][x];if(*t=='c'){*t='.';save.coins+=3;save_game();}else if(*t=='k'){*t='.';uint32_t bit=1UL<<level;if(!(save.treasure&bit)){save.treasure|=bit;save.coins+=15;save_game();}}}
static void step_game(uint8_t *k){bool l=held(k,7,kb_Left),r=held(k,7,kb_Right);if(l){p.vx-=2;p.face=0;}if(r){p.vx+=2;p.face=1;}if(!l&&!r){if(p.vx>0)p.vx--;if(p.vx<0)p.vx++;}if(p.vx>28)p.vx=28;if(p.vx< -28)p.vx=-28;
    static uint8_t buffer,coyote;if(pressed(k,1,kb_2nd))buffer=6;else if(buffer)buffer--;if(p.grounded)coyote=6;else if(coyote)coyote--;if(buffer&&coyote){p.vy=-56;p.grounded=0;buffer=0;coyote=0;}if(!held(k,1,kb_2nd)&&p.vy< -25)p.vy=-25;
    if(pressed(k,2,kb_Alpha))pulse();if(pressed(k,1,kb_Mode)&&p.energy>=3){p.energy-=3;if(level>=15){for(uint8_t y=0;y<MAP_H;y++)for(uint8_t x=0;x<MAP_W;x++)if(room[y][x]=='r')room[y][x]='.';seals=3;flash=18;}else if(level>=5){p.vx=p.face?64:-64;flash=8;}else{p.invuln=24;flash=8;}}
    p.vy+=3;if(p.vy>44)p.vy=44;int ox=p.x,oy=p.y;p.x+=p.vx/4;if(solid(p.x+2,p.y+4)||solid(p.x+14,p.y+4)||solid(p.x+2,p.y+16)||solid(p.x+14,p.y+16))p.x=ox;if(p.x<0)p.x=0;if(p.x>MAP_W*TILE-16)p.x=MAP_W*TILE-16;
    p.y+=p.vy/4;p.grounded=0;if(p.vy>=0&&(solid(p.x+3,p.y+18)||solid(p.x+13,p.y+18))){p.y=(p.y+18)/TILE*TILE-18;p.vy=0;p.grounded=1;coyote=6;}if(p.vy<0&&(solid(p.x+3,p.y+2)||solid(p.x+13,p.y+2))){p.y=oy;p.vy=0;}if(p.y>220){p.y=oy;p.vy=0;}
    for(int y=p.y/TILE;y<=(p.y+17)/TILE;y++)for(int x=p.x/TILE;x<=(p.x+15)/TILE;x++)if(x>=0&&x<MAP_W&&y>=0&&y<MAP_H){char c=room[y][x];if(c=='c'||c=='k')collect(x,y);if(c=='^'&&!p.invuln){uint8_t d=(uint8_t)(12-save.armor*2);p.hp=p.hp>d?p.hp-d:0;p.vy=-25;p.invuln=40;if(!p.hp){save.deaths++;save_game();begin_level(level);return;}}if(c=='d'&&(level%5!=4||seals>=3)){reward();return;}}
    creature+=dir*(level%5==4?2:1);if(creature<230||creature>620)dir=-dir;if(abs(p.x-creature)<18&&!p.invuln){uint8_t d=(uint8_t)(level%5==4?16:10);d=(uint8_t)(d-save.armor*2);p.hp=p.hp>d?p.hp-d:0;p.vy=-22;p.vx=p.x<creature?-28:28;p.invuln=36;if(!p.hp){save.deaths++;save_game();begin_level(level);return;}}
    if(p.invuln)p.invuln--;if(tick%100==0&&p.hp<100+save.health*25)p.hp++;if(tick%20==0&&p.energy<20+save.energy*10)p.energy++;if(flash)flash--;if(p.x-cam>220)cam=p.x-220;if(p.x-cam<68)cam=p.x-68;if(cam<0)cam=0;if(cam>MAP_W*TILE-320)cam=MAP_W*TILE-320;}
static void tile(int x,int y,char c,uint8_t w){if(c=='#'){gfx_SetColor(color(w,1));gfx_FillRect(x,y,16,16);gfx_SetColor(color(w,2));gfx_HorizLine(x,y+2,16);gfx_HorizLine(x+3,y+8,8);gfx_VertLine(x+13,y+4,5);}else if(c=='='){gfx_SetColor(color(w,3));gfx_FillRect(x,y+5,16,8);gfx_SetColor(color(w,4));gfx_HorizLine(x,y+5,16);}else if(c=='^'){gfx_SetColor(color(w,4));gfx_FillTriangle(x,y+15,x+8,y+1,x+15,y+15);}else if(c=='c'){gfx_SetColor(color(w,4));gfx_FillCircle(x+8,y+8,5);gfx_SetColor(color(w,2));gfx_FillCircle(x+8,y+8,2);}else if(c=='k'){gfx_SetColor(color(w,3));gfx_FillRect(x+2,y+5,12,10);gfx_SetColor(color(w,4));gfx_FillRect(x+1,y+2,14,4);gfx_SetColor(color(w,2));gfx_VertLine(x+8,y+6,8);}else if(c=='r'){gfx_SetColor(color(w,4));gfx_FillTriangle(x+8,y+1,x+14,y+8,x+8,y+15);gfx_FillTriangle(x+8,y+1,x+2,y+8,x+8,y+15);}}
static void player_draw(int x,int y){static const char *s[18]={"......DDDD......","....DDHHHHDD....","...DHHHHHHHHD...","...DHHSSHHHHD...","...DHHHHHHHHD...","....DHRRRHD.....","......RRR.......",".....BRRRB......","....BBBWWBBB.....","....BWWWWWWB.....","....BWWWWWWB.....",".....BWWWWB......","......BBBW.......","......LL.LL......",".....LL...LL.....","....LL.....LL....","...DD.......DD...","................"};int bob=p.grounded&&p.vx&&(tick&4)?1:0;for(int yy=0;yy<18;yy++)for(int xx=0;xx<16;xx++){char c=s[yy][xx];uint8_t col=0;if(c=='D')col=color(level/5,2);if(c=='H')col=color(level/5,3);if(c=='S')col=color(level/5,4);if(c=='R')col=color(level/5,5);if(c=='B'||c=='L')col=35;if(c=='W')col=230;if(col){gfx_SetColor(col);gfx_SetPixel(x+(p.face?xx:15-xx),y+bob+yy);}}}
static void draw_game(void){uint8_t w=abyss_levels[level].world;palette(w);gfx_SetColor(color(w,0));gfx_FillScreen(color(w,0));for(int i=0;i<18;i++){int x=i*47-(cam/3)%47;gfx_SetColor(color(w,1));gfx_VertLine(x,40+(i%4)*13,120);gfx_HorizLine(x,75+(i%5)*12,18);}for(uint8_t y=0;y<MAP_H;y++)for(uint8_t x=0;x<MAP_W;x++){char c=room[y][x];int sx=x*TILE-cam,sy=y*TILE;if(sx>=-16&&sx<=320&&(c=='#'||c=='='||c=='^'||c=='c'||c=='k'||c=='r'))tile(sx,sy,c,w);if(c=='d'&&sx>-16&&sx<320){gfx_SetColor(color(w,3));gfx_FillRect(sx+2,sy,12,16);gfx_SetColor(color(w,1));gfx_FillRect(sx+5,sy+3,6,13);}}
    int ex=creature-cam;if(ex>-20&&ex<330){gfx_SetColor(color(w,3));gfx_FillEllipse(ex+8,207,12,7);gfx_SetColor(color(w,4));gfx_FillCircle(ex+12,205,2);}if(level%5==4){gfx_SetColor(color(w,2));gfx_FillEllipse(ex+8,142,34,42);gfx_SetColor(color(w,3));gfx_FillEllipse(ex+8,131,25,20);gfx_SetColor(color(w,4));gfx_FillCircle(ex,130,4);gfx_FillCircle(ex+16,130,4);gfx_SetColor(color(w,4));gfx_FillTriangle(ex-18,113,ex-13,98,ex-8,115);gfx_FillTriangle(ex+34,113,ex+29,98,ex+24,115);}
    if(!p.invuln||!(tick&2))player_draw(p.x-cam,p.y);gfx_SetColor(0);gfx_FillRect(0,0,320,22);gfx_SetColor(color(w,2));gfx_FillRect(8,7,104,8);gfx_SetColor(color(w,4));gfx_FillRect(10,9,p.hp*100/(100+save.health*25),4);gfx_SetColor(color(w,4));gfx_FillRect(8,17,104,3);gfx_SetColor(color(w,3));gfx_FillRect(10,18,p.energy*100/(20+save.energy*10),1);gfx_SetTextFGColor(255);gfx_SetTextBGColor(0);draw_text(126,5,abyss_levels[level].name);draw_text(265,5,"C");num(276,5,save.coins,3);if(level%5==4){draw_text(10,25,"RUNE SEALS");for(uint8_t i=0;i<3;i++){gfx_SetColor(i<seals?color(w,4):color(w,1));gfx_FillCircle(97+i*14,30,4);}}if(flash){gfx_SetColor(color(w,4));gfx_Circle(p.x-cam+8,p.y+9,14);}}
static void panel(const char *title){gfx_SetColor(0);gfx_FillScreen(0);for(int y=0;y<240;y+=18){gfx_SetColor(color(0,1));gfx_HorizLine(0,y,320);}gfx_SetColor(color(0,3));gfx_FillRect(16,20,288,32);gfx_SetTextFGColor(255);gfx_SetTextBGColor(color(0,3));draw_text(25,29,title);gfx_SetTextBGColor(0);}
static void draw_menu(void){if(scene==TITLE){panel("ABYSS");draw_text(28,78,"THE DEEP REMEMBERS YOUR NAME");draw_text(28,116,"2ND OR ENTER  BEGIN DESCENT");draw_text(28,148,"ARROWS MOVE   ALPHA RUNE   MODE ABILITY");gfx_SetColor(color(3,4));gfx_FillCircle(264,126,26);gfx_SetColor(color(3,2));gfx_FillCircle(264,126,18);gfx_SetColor(color(3,4));gfx_FillTriangle(264,103,246,129,264,151);gfx_FillTriangle(264,103,282,129,264,151);}else if(scene==LOBBY){panel("THE WAYSTATION");const char *o[4]={"PLAY","UPGRADES","COLLECTION","STATS"};for(uint8_t i=0;i<4;i++){gfx_SetTextFGColor(i==choice?color(0,4):255);gfx_SetTextXY(42,75+i*29);gfx_PrintString(i==choice?"> ":"  ");gfx_PrintString(o[i]);}gfx_SetTextFGColor(255);draw_text(185,84,"BETWEEN THE FOUR WORLDS");draw_text(185,117,"COINS");num(235,117,save.coins,4);draw_text(185,146,"DEPTH");num(235,146,save.unlocked,2);draw_text(24,211,"UP/DOWN SELECT    ENTER CONFIRM");}else if(scene==SELECT){panel("CHOOSE A DESCENT");const char *world[4]={"FORGOTTEN CRYPT","SUNKEN MINES","INFERNAL DEPTHS","THE VOID"};gfx_SetTextFGColor(color(level/5,4));draw_text(38,64,world[level/5]);for(uint8_t i=0;i<5;i++){uint8_t n=(level/5)*5+i;gfx_SetTextFGColor(n<save.unlocked?255:color(level/5,1));gfx_SetTextXY(42,87+i*23);gfx_PrintString(n==level?"> ":"  ");num(59,87+i*23,n+1,2);draw_text(83,87+i*23,abyss_levels[n].name);if(n%5==4)draw_text(230,87+i*23,"GUARDIAN");}draw_text(20,208,"LEFT/RIGHT WORLD   UP/DOWN LEVEL");}else if(scene==UPGRADE){panel("WAYSTATION UPGRADES");const char *o[3]={"ARMOR","MAXIMUM HEALTH","ENERGY CAPACITY"};uint8_t vals[3]={save.armor,save.health,save.energy};for(uint8_t i=0;i<3;i++){gfx_SetTextFGColor(i==choice?color(0,4):255);gfx_SetTextXY(40,82+i*34);gfx_PrintString(i==choice?"> ":"  ");gfx_PrintString(o[i]);num(240,82+i*34,vals[i],1);draw_text(258,82+i*34,"/3");draw_text(42,96+i*34,"COST");num(82,96+i*34,(i==0?25+save.armor*30:i==1?35+save.health*40:20+save.energy*25),3);}draw_text(32,207,"ENTER BUY   CLEAR BACK   COINS");num(228,207,save.coins,4);}else if(scene==PAUSE){panel("DESCENT PAUSED");draw_text(38,91,"ENTER RESUME");draw_text(38,124,"CLEAR WAYSTATION");}else if(scene==ENDING){panel("THE ABYSS REMEMBERS");draw_text(25,78,"The final seal opens; the darkness lets go.");draw_text(25,110,"Every lost name returns to the stars.");draw_text(25,156,"A small dawn begins beyond the deep.");draw_text(25,207,"ENTER  WAYSTATION");}else if(scene==COLLECTION){panel("RELICS & DISCOVERIES");draw_text(32,77,"GUARDIANS SOLVED");num(230,77,bits(save.complete&((1UL<<4)|(1UL<<9)|(1UL<<14)|(1UL<<19))),1);draw_text(32,111,"TREASURE ROOMS");num(230,111,bits(save.treasure),2);draw_text(32,145,"RUNE SECRETS");num(230,145,bits(save.secrets),2);draw_text(32,180,"COMPLETION");num(230,180,(bits(save.complete)*5+bits(save.treasure)+bits(save.secrets)),3);draw_text(32,207,"CLEAR BACK");}else{panel("DESCENT RECORD");draw_text(32,77,"LEVELS CLEARED");num(230,77,bits(save.complete),2);draw_text(32,111,"GUARDIAN SEALS");num(230,111,bits(save.complete&((1UL<<4)|(1UL<<9)|(1UL<<14)|(1UL<<19))),1);draw_text(32,145,"TREASURES FOUND");num(230,145,bits(save.treasure),2);draw_text(32,179,"FALLS RECORDED");num(230,179,save.deaths,4);draw_text(32,207,"CLEAR BACK");}}
int main(void){uint8_t k[8];load_game();kb_SetMode(MODE_3_CONTINUOUS);gfx_Begin();gfx_SetDrawBuffer();ti_SetGCBehavior(before_gc,after_gc);for(;;){input(k);tick++;if(scene==TITLE){if(pressed(k,1,kb_2nd)||pressed(k,6,kb_Enter)){scene=LOBBY;choice=0;}}else if(scene==LOBBY){if(pressed(k,7,kb_Up)&&choice)choice--;if(pressed(k,7,kb_Down)&&choice<3)choice++;if(pressed(k,6,kb_Enter)){if(choice==0){scene=SELECT;level=0;}else if(choice==1){scene=UPGRADE;choice=0;}else if(choice==2)scene=COLLECTION;else scene=STATS;}}else if(scene==SELECT){if(pressed(k,7,kb_Left)&&level>=5)level-=5;if(pressed(k,7,kb_Right)&&level<15)level+=5;if(pressed(k,7,kb_Up)&&level%5)level--;if(pressed(k,7,kb_Down)&&level%5<4&&level<19)level++;if(pressed(k,6,kb_Enter)&&level<save.unlocked)begin_level(level);if(pressed(k,6,kb_Clear))scene=LOBBY;}else if(scene==UPGRADE){if(pressed(k,7,kb_Up)&&choice)choice--;if(pressed(k,7,kb_Down)&&choice<2)choice++;if(pressed(k,6,kb_Enter)){uint8_t *v=choice==0?&save.armor:choice==1?&save.health:&save.energy;uint16_t cost=choice==0?25+save.armor*30:choice==1?35+save.health*40:20+save.energy*25;if(*v<3&&save.coins>=cost){save.coins-=cost;(*v)++;save_game();}}if(pressed(k,6,kb_Clear))scene=LOBBY;}else if(scene==PLAY){if(pressed(k,6,kb_Clear))scene=PAUSE;else step_game(k);}else if(scene==PAUSE){if(pressed(k,6,kb_Enter))scene=PLAY;if(pressed(k,6,kb_Clear))scene=LOBBY;}else if(pressed(k,6,kb_Clear)||pressed(k,6,kb_Enter))scene=LOBBY;
        palette(level/5);gfx_SetDrawBuffer();if(scene==PLAY)draw_game();else draw_menu();gfx_SwapDraw();gfx_Wait();memcpy(prior,k,8);}}
